func (Keys) GuildMembersPrefix(guildID string) string {
	return fmt.Sprintf("%s:guild:%s:member:", KeyNamespace, guildID)
}

// Member devuelve la clave cacheada del estado de un miembro concreto.
func (Keys) Member(guildID, userID string) string {
	return fmt.Sprintf("%s:guild:%s:member:%s", KeyNamespace, guildID, userID)
}

// -------------------------------------------------------------
// Antiraid
// -------------------------------------------------------------

// AntiraidWindow devuelve la clave del sorted set que materializa la
// ventana deslizante de eventos antiraid por guild y bucket.
// bucket puede ser: "joins", "messages", "mentions", "links".
func (Keys) AntiraidWindow(guildID, bucket string) string {
	return fmt.Sprintf("%s:antiraid:%s:window:%s", KeyNamespace, guildID, bucket)
}

// AntiraidScore acumula el score actual de un usuario bajo vigilancia.
func (Keys) AntiraidScore(guildID, userID string) string {
	return fmt.Sprintf("%s:antiraid:%s:score:%s", KeyNamespace, guildID, userID)
}

// AntiraidLeaderboard es el ranking de usuarios con mayor score en el guild.
func (Keys) AntiraidLeaderboard(guildID string) string {
	return fmt.Sprintf("%s:antiraid:%s:leaderboard", KeyNamespace, guildID)
}

