// scope ejemplos: "cmd.purge", "cmd.ban", "ai.ask".
func (Keys) Cooldown(scope, guildID, subjectID string) string {
	return fmt.Sprintf("%s:cooldown:%s:%s:%s", KeyNamespace, scope, guildID, subjectID)
}

// -------------------------------------------------------------
// Cerebras / IA
// -------------------------------------------------------------

// AIResponse cachea respuestas de Cerebras indexadas por hash de prompt.
// El hash debe incluir system + user para que variaciones del system
// prompt no colisionen con respuestas antiguas.
func (Keys) AIResponse(promptHash string) string {
	return fmt.Sprintf("%s:ai:resp:%s", KeyNamespace, promptHash)
}

// AIRateLimit marca la ventana de rate limit por usuario IA.
func (Keys) AIRateLimit(userID string) string {
	return fmt.Sprintf("%s:ai:rl:%s", KeyNamespace, userID)
}

