func (Keys) SessionPrefix() string {
	return fmt.Sprintf("%s:session:", KeyNamespace)
}

// LiveMessage guarda el estado serializado de un live message en curso.
func (Keys) LiveMessage(channelID, messageID string) string {
	return fmt.Sprintf("%s:live:%s:%s", KeyNamespace, channelID, messageID)
}

// -------------------------------------------------------------
// Stats
// -------------------------------------------------------------

// StatsLive es el hash de contadores en vivo por guild (dashboard).
// Campos: incidents_24h, actions_24h, raids_blocked, ai_calls.
func (Keys) StatsLive(guildID string) string {
	return fmt.Sprintf("%s:stats:live:%s", KeyNamespace, guildID)
}

// StatsGlobal es el contador agregado de toda la instancia del bot.
func (Keys) StatsGlobal() string {
	return fmt.Sprintf("%s:stats:global", KeyNamespace)
}

// -------------------------------------------------------------
// Distributed locks
// -------------------------------------------------------------

// Lock es una clave de bloqueo distribuido por recurso.
// Formato: lock:<resource>:<identifier>. Ejemplo: lock:guild-sync:123456789.
func (Keys) Lock(resource, identifier string) string {
	return fmt.Sprintf("%s:lock:%s:%s", KeyNamespace, resource, identifier)
}

