func TTL(d time.Duration) time.Duration { return d }

// BuildPrefixJoin une un prefijo con sufijos saneados por ':'. Uso interno
// para construir claves ad-hoc sin exponer fmt.Sprintf al call-site.
func BuildPrefixJoin(prefix string, parts ...string) string {
	var sb strings.Builder
	sb.WriteString(prefix)
	for _, p := range parts {
		sb.WriteByte(':')
		sb.WriteString(p)
	}
	return sb.String()
}
